const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8');
  let idx = 0;
  const len = data.length;

  function nextInt() {
    while (idx < len && data.charCodeAt(idx) <= 32) idx++;
    let num = 0;
    while (idx < len && data.charCodeAt(idx) > 32) {
      num = num * 10 + (data.charCodeAt(idx) - 48);
      idx++;
    }
    return num;
  }

  const n = nextInt();
  const m = nextInt();

  const adj = new Array(n + 1);
  for (let i = 1; i <= n; i++) adj[i] = [];

  for (let e = 0; e < m; e++) {
    const x = nextInt();
    const y = nextInt();
    adj[x].push(y);
    adj[y].push(x);
  }

  const visited = new Uint8Array(n + 1);
  const mark = new Int32Array(n + 1);
  let token = 1;

  for (let start = 1; start <= n; start++) {
    if (visited[start]) continue;

    const stack = [start];
    visited[start] = 1;

    const comp = [];
    let size = 0;
    let edgeSum = 0;

    while (stack.length) {
      const u = stack.pop();
      comp.push(u);
      size++;

      const neigh = adj[u];
      edgeSum += neigh.length;

      for (let j = 0; j < neigh.length; j++) {
        const v = neigh[j];
        if (!visited[v]) {
          visited[v] = 1;
          stack.push(v);
        }
      }
    }

    if (edgeSum !== size * (size - 1)) {
      let v = -1;

      for (let i = 0; i < comp.length; i++) {
        const u = comp[i];
        if (adj[u].length < size - 1) {
          v = u;
          break;
        }
      }

      const neigh = adj[v];
      for (let j = 0; j < neigh.length; j++) {
        mark[neigh[j]] = token;
      }

      for (let i = 0; i < comp.length; i++) {
        const u = comp[i];
        if (u !== v && mark[u] !== token) {
          console.log(v, u);
          return;
        }
      }

      token++;
    }
  }

  console.log(-1);
}

main();
